#!/usr/bin/env python3
"""Load each historical RDB snapshot under Redis 7.2 twice (default limits and
forced-down compact-encoding limits) and emit /results/encodings.json."""
import json, os, shutil, subprocess, sys, time

SRC_RDB = "/data/rdb"
WORK = "/tmp/rdbwork"
SERVER = "/app/src/redis-server"
CLI = "/app/src/redis-cli"
PORT = 6381

# file -> (payload key, tight-limit config parameter)
SPECS = [
    ("hash-zipmap.rdb",    "hash", "hash-max-listpack-entries"),
    ("hash-ziplist.rdb",   "hash", "hash-max-listpack-entries"),
    ("zset-ziplist.rdb",   "zset", "zset-max-listpack-entries"),
    ("list-quicklist.rdb", "list", "list-max-listpack-size"),
]


def cli(port, *args, json_out=False):
    cmd = [CLI, "-h", "127.0.0.1", "-p", str(port)]
    if json_out:
        cmd.append("--json")
    cmd += [str(a) for a in args]
    r = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
    if r.returncode != 0:
        raise RuntimeError(f"redis-cli {args} failed: {r.stderr.strip()}")
    return r.stdout.strip()


def start(workdir, dbfilename, port, extra=()):
    """Start a server on `port` with dir=workdir, dbfilename, no password."""
    log = os.path.join(workdir, "server.log")
    cmd = [SERVER,
           "--dir", workdir,
           "--dbfilename", dbfilename,
           "--port", str(port),
           "--bind", "127.0.0.1",
           "--save", "",            # never rewrite the snapshot copy
           "--appendonly", "no",
           "--daemonize", "no",
           "--logfile", log]
    for k, v in extra:
        cmd += [f"--{k}", str(v)]
    proc = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    for _ in range(200):
        if proc.poll() is not None:
            sys.stderr.write(open(log).read())
            raise RuntimeError(f"server exited early (rc={proc.returncode})")
        try:
            if cli(port, "PING") == "PONG":
                return proc, log
        except Exception:
            pass
        time.sleep(0.1)
    raise RuntimeError("server did not become ready")


def stop(proc, port):
    try:
        subprocess.run([CLI, "-h", "127.0.0.1", "-p", str(port), "SHUTDOWN", "NOSAVE"],
                       capture_output=True, text=True, timeout=15)
    except Exception:
        pass
    try:
        proc.wait(timeout=15)
    except subprocess.TimeoutExpired:
        proc.kill()
        proc.wait(timeout=10)


def num(s):
    f = float(s)
    return int(f) if f.is_integer() else f


def payload(port, key, typ):
    if typ == "hash":
        return json.loads(cli(port, "HGETALL", key, json_out=True))
    if typ == "list":
        return json.loads(cli(port, "LRANGE", key, 0, -1, json_out=True))
    if typ == "zset":
        flat = json.loads(cli(port, "ZRANGE", key, 0, -1, "WITHSCORES", json_out=True))
        pairs = [{"member": flat[i], "score": num(flat[i + 1])}
                 for i in range(0, len(flat), 2)]
        return sorted(pairs, key=lambda p: p["member"])
    raise RuntimeError(f"unexpected type {typ}")


def private_copy(fname, tag):
    """Working dir containing only a copy of this one snapshot."""
    d = os.path.join(WORK, f"{fname}.{tag}")
    shutil.rmtree(d, ignore_errors=True)
    os.makedirs(d)
    shutil.copy2(os.path.join(SRC_RDB, fname), os.path.join(d, fname))
    return d


def run(fname, key, tag, extra):
    d = private_copy(fname, tag)
    proc, log = start(d, fname, PORT, extra)
    try:
        typ = cli(PORT, "TYPE", key)
        enc = cli(PORT, "OBJECT", "ENCODING", key)
        keys = sorted(json.loads(cli(PORT, "KEYS", "*", json_out=True)))
        data = payload(PORT, key, typ)
        print(f"  {tag:8s} type={typ} encoding={enc} keys={keys}")
        return typ, enc, data
    finally:
        stop(proc, PORT)


def main():
    shutil.rmtree(WORK, ignore_errors=True)
    os.makedirs(WORK)
    files = []
    for fname, key, param in SPECS:
        print(f"== {fname} (key {key!r}, tight via {param}=1)")
        t_def, e_def, data = run(fname, key, "default", ())
        t_tight, e_tight, data_t = run(fname, key, "tight", ((param, 1),))
        if t_def != t_tight:
            raise RuntimeError(f"{fname}: type differs between runs")
        if data != data_t:
            raise RuntimeError(f"{fname}: payload differs between runs: {data} vs {data_t}")
        files.append({
            "file": fname,
            "key": key,
            "type": t_def,
            "default_encoding": e_def,
            "tight_encoding": e_tight,
            "fields": data,
        })
    os.makedirs("/results", exist_ok=True)
    with open("/results/encodings.json", "w", encoding="utf-8") as f:
        json.dump({"files": files}, f, indent=2, ensure_ascii=False)
        f.write("\n")
    print("\nwrote /results/encodings.json")


if __name__ == "__main__":
    main()

